/**
 * Multi-select interactive UI component
 *
 * Terminal-based multi-select picker with keyboard navigation.
 * Used by install/uninstall commands for tool selection.
 */
import { writeStdout } from "../../../src/platform/index.js";
import { getStdinReader, setRawMode } from "../../../src/platform/index.js";
import { bold, brand, dim, muted } from "../colors.js";
import { cursor, screen } from "../ansi.js";
import { isTTY } from "../../utils/index.js";
const COL_1 = `\x1b[1G`;
function write(s) {
    writeStdout(s);
}
function clearLines(n) {
    for (let i = 0; i < n; i++)
        write(cursor.up() + screen.clearLine);
    write(COL_1);
}
export async function multiSelect(options, config) {
    const checkboxStyle = config.checkboxStyle ?? ((value) => value);
    const focusLabelStyle = config.focusLabelStyle ?? ((s) => s);
    const blurLabelStyle = config.blurLabelStyle ?? muted;
    const descriptionStyle = config.descriptionStyle ?? dim;
    const initialSelected = options.filter((o) => o.selected).map((o) => o.value);
    if (!isTTY())
        return initialSelected;
    let idx = 0;
    let lines = 0;
    const selected = new Set(initialSelected);
    function draw() {
        if (lines > 0)
            clearLines(lines);
        console.log();
        console.log("  " + bold(config.title) + " " + dim("(space to toggle, enter to confirm)"));
        console.log("  " + dim(config.subtitle));
        console.log();
        lines = 4;
        for (let i = 0; i < options.length; i++) {
            const opt = options[i];
            const isCurrent = i === idx;
            const isSelected = selected.has(opt.value);
            const pointer = isCurrent ? brand("❯") : " ";
            const checkbox = isSelected ? checkboxStyle("[✓]") : dim("[ ]");
            const label = isCurrent ? focusLabelStyle(opt.label) : blurLabelStyle(opt.label);
            console.log(`  ${pointer} ${checkbox} ${label.padEnd(24)} ${descriptionStyle(opt.description)}`);
            lines++;
        }
        if (config.hint) {
            console.log();
            console.log("  " + dim("Tip: " + config.hint));
            lines += 2;
        }
        console.log();
        console.log("  " + dim("↑↓ navigate · space toggle · enter confirm · a all · n none"));
        lines += 2;
    }
    write(cursor.hide);
    draw();
    setRawMode(true);
    const reader = getStdinReader();
    const dec = new TextDecoder();
    let result = null;
    try {
        while (true) {
            const { value, done } = await reader.read();
            if (done)
                break;
            const key = dec.decode(value);
            if (key === "\x03" || key === "q" || key === "Q") {
                result = null;
                break;
            }
            if (key === "\r" || key === "\n") {
                result = Array.from(selected);
                break;
            }
            if (key === " ") {
                const val = options[idx].value;
                if (selected.has(val))
                    selected.delete(val);
                else
                    selected.add(val);
                draw();
                continue;
            }
            if (key === "\x1b[A" || key === "k") {
                idx = idx > 0 ? idx - 1 : options.length - 1;
                draw();
                continue;
            }
            if (key === "\x1b[B" || key === "j") {
                idx = idx < options.length - 1 ? idx + 1 : 0;
                draw();
                continue;
            }
            if (key === "a" || key === "A") {
                for (const o of options)
                    selected.add(o.value);
                draw();
                continue;
            }
            if (key === "n" || key === "N") {
                selected.clear();
                draw();
                continue;
            }
        }
    }
    finally {
        reader.releaseLock();
        setRawMode(false);
    }
    write(cursor.show);
    clearLines(lines);
    return result;
}
